//! Wide arithmetic vectors generated by independent Python Fraction semantics.
use conduit_core::{ExactNumericWork, ExactRational, EXACT_RATIONAL_MAX_ENCODED_BYTES};
use serde::Deserialize;
#[derive(Deserialize)]
struct Row {
    a: [String; 2],
    b: [String; 2],
    add: String,
    subtract: String,
    multiply: String,
    divide: String,
    order: i8,
}
fn work() -> ExactNumericWork {
    ExactNumericWork::new(100_000_000)
}
fn rational(pair: &[String; 2]) -> ExactRational {
    ExactRational::parse_decimal(&pair[0], &mut work())
        .unwrap()
        .checked_divide(
            ExactRational::parse_decimal(&pair[1], &mut work()).unwrap(),
            &mut work(),
        )
        .unwrap()
}
fn check(value: ExactRational, expected: &str) {
    let (pairs, remainder) = expected.as_bytes().as_chunks::<2>();
    assert!(remainder.is_empty());
    let bytes: Vec<u8> = pairs
        .iter()
        .map(|pair| u8::from_str_radix(core::str::from_utf8(pair).unwrap(), 16).unwrap())
        .collect();
    let mut actual = [0; EXACT_RATIONAL_MAX_ENCODED_BYTES];
    let length = value.encode(&mut actual).unwrap();
    assert_eq!(&actual[..length], bytes);
    assert_eq!(ExactRational::decode(&bytes, &mut work()).unwrap(), value);
}
#[test]
fn wide_exact_arithmetic_matches_independent_fraction_vectors() {
    let rows: Vec<Row> =
        serde_json::from_str(include_str!("fixtures/exact_rational_vectors.json")).unwrap();
    for row in rows {
        let a = rational(&row.a);
        let b = rational(&row.b);
        check(a.checked_add(b, &mut work()).unwrap(), &row.add);
        check(a.checked_subtract(b, &mut work()).unwrap(), &row.subtract);
        check(a.checked_multiply(b, &mut work()).unwrap(), &row.multiply);
        check(a.checked_divide(b, &mut work()).unwrap(), &row.divide);
        assert_eq!(
            a.checked_compare(b, &mut work()).unwrap(),
            row.order.cmp(&0)
        );
    }
}
